def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chair_patches = image_patch.find("chair")
    bag_patches = image_patch.find("bag")

    if not chair_patches or len(bag_patches) < 2:
        return image_patch

    chairs = sorted(chair_patches, key=lambda p: p.area)
    chairs_with_bags = []

    for chair in chairs:
        bags_on_chair = [bag for bag in bag_patches if chair.overlaps_with(*bag.bbox)]
        if len(bags_on_chair) >= 2:
            chairs_with_bags.append((chair, bags_on_chair))

    if not chairs_with_bags:
        return image_patch

    return max(chairs_with_bags, key=lambda x: sum(bag.area for bag in x[1]))[0]

