def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boat_patches = image_patch.find("boat")
    if len(boat_patches) < 3: 
        return image_patch

    boat_patches.sort(key=lambda p: p.horizontal_center)
    middle_boat = boat_patches[len(boat_patches) // 2]

    left_boats = [b for b in boat_patches if b.horizontal_center < middle_boat.horizontal_center]
    right_boats = [b for b in boat_patches if b.horizontal_center > middle_boat.horizontal_center]

    if not left_boats or not right_boats:
        return image_patch

    left_most_right_boat = max(left_boats, key=lambda b: b.horizontal_center)
    right_most_left_boat = min(right_boats, key=lambda b: b.horizontal_center)

    if is_between_3d(middle_boat, left_most_right_boat, right_most_left_boat):
        return middle_boat
    elif is_between_3d(left_most_right_boat, middle_boat, right_most_left_boat):
        return left_most_right_boat
    else:
        return right_most_left_boat

